import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    expected = [
        "UNIQ-NAME", "VALUE", "TYPE", "CONFIDENCE",
        "SEVERITY", "PRODUCT", "COMMENT"
    ]

    def normalized_header(row):
        if not row:
            return []
        fields = [field.strip().upper() for field in row]
        fields[0] = fields[0].lstrip("\ufeff").lstrip()
        if fields[0].startswith("#"):
            fields[0] = fields[0][1:].lstrip()
        return fields

    header_index = None
    for index, row in enumerate(records):
        if normalized_header(row) == expected:
            header_index = index
            break

    if header_index is None:
        for index, row in enumerate(records):
            if row and any(field.strip() for field in row):
                if len(row) == 1 and row[0].lstrip("\ufeff \t").startswith("#"):
                    continue
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    columns[0] = columns[0].lstrip("\ufeff")
    if columns[0].lstrip().startswith("#"):
        columns[0] = columns[0].lstrip()[1:].lstrip()

    width = len(columns)
    rows = []
    for row in records[header_index + 1:]:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
